def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    period = max(max(row) for row in grid)

    # Below the diagonal, each column shows the unshifted sequence.
    base = []
    for c in range(w):
        vals = [grid[r][c] for r in range(c + 1, h) if grid[r][c] != 0]
        if vals:
            base.append(Counter(vals).most_common(1)[0][0])
        else:
            base.append(None)

    # Extend the sequence cyclically if a column has no lower-triangle samples.
    for c in range(w):
        if base[c] is None:
            base[c] = ((base[c - 1] if c else 1) % period) + 1

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                v = base[c]
                # On and above the diagonal, values are one step earlier.
                if c >= r:
                    v = (v - 2) % period + 1
                out[r][c] = v
    return out
